+         *
+         * @param urlSafe URL-safe encoding policy, null resets to the default.
+         * @return {@code this} instance.
+         */
+        public Builder setUrlSafe(final boolean urlSafe) {
+            return setEncodeTable(toUrlSafeEncodeTable(urlSafe));
